// Embedded TrueType font data (Segoe UI Normal & Bold subset) supporting Unicode Rupee symbol (U+20B9)
import type { jsPDF } from 'jspdf';

export const PDF_FONT = 'SegoeUI';

const segoeuiNormalBase64 = "";
const segoeuiBoldBase64 = "";

export function registerPdfFonts(doc: jsPDF): void {
  doc.addFileToVFS('SegoeUI.ttf', segoeuiNormalBase64);
  doc.addFont('SegoeUI.ttf', PDF_FONT, 'normal');
  doc.addFileToVFS('SegoeUI-Bold.ttf', segoeuiBoldBase64);
  doc.addFont('SegoeUI-Bold.ttf', PDF_FONT, 'bold');
  doc.setFont(PDF_FONT, 'normal');
}
